        return original_message

class LoggerWrapper(
    logging.getLogger("__name__")
):
    def log(self, level, message, phone=None):
        if phone:
            record = logging.LogRecord(
                name=self.name,
                level=level,
                pathname="",
                lineno=None,
                msg="{message}",
                args="",
                exc_info="",
                extra={'phone': phone}
            )
            self.handle(*self._process_record(record))
        else:
            self.error(message)

    def _process_record(self, record):
        formatter = MaskedFormatter("%(event)s %(levelname)s %(timestamp)s")
        return formatter.format(record)

    def error(self, message):
        logging.error(message)

